import{_ as a,o,c as t,ag as i}from"./chunks/framework.Drp2S_UI.js";const h=JSON.parse('{"title":"T19 文档模型与原生布局分离","description":"","frontmatter":{},"headers":[],"relativePath":"guide/native-model-separation.md","filePath":"guide/native-model-separation.md","lastUpdated":1792653875000}'),c={name:"guide/native-model-separation.md"};function d(r,e,l,s,n,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="t19-文档模型与原生布局分离" tabindex="-1">T19 文档模型与原生布局分离 <a class="header-anchor" href="#t19-文档模型与原生布局分离" aria-label="Permalink to &quot;T19 文档模型与原生布局分离&quot;">​</a></h1><h2 id="原生路径" tabindex="-1">原生路径 <a class="header-anchor" href="#原生路径" aria-label="Permalink to &quot;原生路径&quot;">​</a></h2><p>删除 <code>mapToLegacyRow.ts</code> 和 <code>projectNativeRows.ts</code>。 原生文本不再转换为带 <code>metrics/visualLeft/engineLine</code> 的旧行元素。 <code>createTextRows</code> 仅建立容器流记录：持有 <code>TextLine</code>、来源元素引用和显式 <code>sourceIndices</code>，不改写来源模型，也不复制 HarfBuzz glyph 数据。 表格、对象同样携带各自原生节点；缩放后的行宽、高只供宿主推进容器流。</p><p>正文、页眉页脚、表格、命中、搜索和编辑入口使用原生 <code>LayoutRow</code>。 内部访问器为 <code>getLayoutRows/getLayoutRowList/getRawLayoutRows/getLayoutPages</code>。 旧 <code>IRow/IRowElement</code> 仅保留给兼容输出、Particle 绘制边界以及 T20 待删旧代码。 它们不再是新布局的数据源。</p><p>位置 DTO 的 metrics 由原生 cluster、caret、inline 和 label 几何按需生成。 零墨迹、隐藏和空值来源仍保留 source 映射。字号上、下标计算不再回写 <code>actualSize</code>； 超链接/标签默认样式由排版和绘制解析，不再隐式改写文档元素。 <code>GlyphRenderer.drawNativeLine</code> 直接使用 <code>TextLine</code> 的真实 font/glyph 与偏移， 文字颜色和隐藏状态可在 paint 时读取当前模型，不需要旧 <code>engineLine</code>。 对象及装饰 Particle 所需的兼容字段只在调用时临时生成。</p><h2 id="表格和页眉" tabindex="-1">表格和页眉 <a class="header-anchor" href="#表格和页眉" aria-label="Permalink to &quot;表格和页眉&quot;">​</a></h2><p>单元格运行时宽高、行/位置列表、合并单元格坐标等位于 WeakMap。 非枚举访问器兼容现有表格工具，JSON/保存/复制/历史不再遍历这些布局树。 单元格的 <code>value</code>、ID、跨行跨列、样式和自定义数据保留在文档模型中。 表格分组需要的运行时几何显式读取 sidecar，不依赖深拷贝文档时夹带布局状态。</p><p>页眉页脚的纸张方向变体拥有各自的表格容器状态。 激活某一变体只更新容器布局兼容视图，不向文字元素写 metrics 或视觉索引。 块对象保留真实语义来源，交互尺寸单独存放，拖动修改仍作用于原始文档对象。</p><h2 id="输出和历史" tabindex="-1">输出和历史 <a class="header-anchor" href="#输出和历史" aria-label="Permalink to &quot;输出和历史&quot;">​</a></h2><p><code>getRowList/getOriginalRowList/getRawRowList/getPageRowList</code> 以及 <code>LayoutHostAdapter.layoutParagraphToRows</code> 保留为兼容输出边界。 每次返回独立快照，旧字段由原生节点生成；修改快照不影响模型或缓存。 运行时使用 <code>layoutParagraphRows</code> 等原生入口，不调用这些快照方法。 按页导出按来源索引去重并恢复文档顺序，跨栏/跨页片段不会重复保存同一个表格。</p><p>历史克隆会剔除旧排版瞬态字段和容器缓存，保留 ID、组、控件和样式等语义。 <code>extension</code> 中同名的用户字段不会被清理；共享扩展对象的引用关系在快照和 恢复时保留，避免撤销后原来可以合并的相邻文本被拆成不同的保存结构。</p><h2 id="验证范围" tabindex="-1">验证范围 <a class="header-anchor" href="#验证范围" aria-label="Permalink to &quot;验证范围&quot;">​</a></h2><ul><li>冻结原始文字元素后完成完整/增量排版，确认无排版字段回写。</li><li>兼容输出快照独立，原生 source、scope、ID 和零墨迹来源映射完整。</li><li>保存、复制结构、HTML 文字/样式往返、表格 ID、历史和组坐标保持语义。</li><li>原生段落、对象、表格、页眉、测量、交互与完整/增量差分定向检查。</li><li>浏览器覆盖 LTR/RTL、IME、选区、分页分栏、重复表头和跨页单元格编辑。</li></ul><p>本阶段定向验证通过：23 个 Vitest 文件共 143 项、4 个 Cypress 文件共 17 项； TypeScript、相关文件 ESLint、ESM 库构建和 <code>test:package</code> 包消费检查通过。</p><p>T20 再删除隔离的旧循环、Particle 文字分支及模式开关；全量回归仍留到 T22。</p>',15)])])}const g=a(c,[["render",d]]);export{h as __pageData,g as default};
